-- Amaal Telecoms mobile phone master catalogue data from Mobile_Phone_Catalogue_Master_2026.md (27 Aug 2026).
-- Additive/repeat-safe data synchronization. No DELETE/TRUNCATE/DROP/reset.

UPDATE products p SET name='Samsung Galaxy S20+',slug='samsung-galaxy-s20-plus',updated_at=now() WHERE p.name='Samsung Galaxy S20' AND EXISTS (SELECT 1 FROM product_variants v WHERE v.product_id=p.id AND v.variant_name='Samsung Galaxy S20+');
