CREATE TEMP TABLE _maal_phone_products(brand text,name text,slug text,family text,model text,category_slug text) ON COMMIT DROP;
CREATE TEMP TABLE _maal_phone_variants(brand text,product_slug text,family text,model text,storage text,ram text,variant_name text,sku text,network text) ON COMMIT DROP;
WITH ranked AS (SELECT v.id,v.product_id,vv.sku,vv.variant_name,vv.storage,ROW_NUMBER() OVER(PARTITION BY v.product_id ORDER BY vv.sku) rn FROM product_variants v JOIN products p ON p.id=v.product_id JOIN _maal_phone_variants vv ON vv.product_slug=p.slug WHERE v.storage='' AND v.sku <> vv.sku AND NOT EXISTS(SELECT 1 FROM sale_lines sl WHERE sl.variant_id=v.id) AND NOT EXISTS(SELECT 1 FROM order_lines ol WHERE ol.variant_id=v.id) AND NOT EXISTS(SELECT 1 FROM serialized_units su WHERE su.variant_id=v.id)) UPDATE product_variants v SET sku=r.sku,variant_name=r.variant_name,storage=r.storage,updated_at=now() FROM ranked r WHERE r.id=v.id AND r.rn=1;
