INSERT INTO products(name,slug,brand_id,category_id,product_type,short_description,description,specifications,status,website_visibility,featured) SELECT d.name,d.slug,b.id,c.id,'Phone','Master mobile-phone catalogue record. No stock has been received.','Master mobile-phone catalogue record sourced from Mobile_Phone_Catalogue_Master_2026.md.',jsonb_build_object('catalogue_source','Mobile_Phone_Catalogue_Master_2026.md','catalogue_reference_date','2026-08-27','family',d.family,'model',d.model,'catalogue_status','Master catalogue baseline'),'Active','Hidden',false FROM _maal_phone_products d JOIN brands b ON b.name=d.brand JOIN product_categories c ON c.slug=d.category_slug ON CONFLICT(slug) DO UPDATE SET brand_id=EXCLUDED.brand_id,category_id=EXCLUDED.category_id,product_type='Phone',specifications=EXCLUDED.specifications,status=CASE WHEN products.status='Archived' THEN products.status ELSE 'Active' END,updated_at=now();
